package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Bee;
import net.minecraft.world.phys.Vec3;
import static io.github.campione01.mineclientbridge.LocalSegmentEngineChecks.*;
/** Unchanged production native readers/controllers and extracted owning-thread row reader; engine values synthetic. */
public final class BeeRouteEngineChecks {
 static int assertions;static JsonArray cases=new JsonArray();
 static void ok(boolean b,String why){assertions++;if(!b)throw new AssertionError(why);}
 static void scenario(String name,Runnable r){r.run();cases.add(name);System.out.println("PASS "+name);}
 static ClientActionRequest.Rejected refused(Runnable r){assertions++;try{r.run();}catch(ClientActionRequest.Rejected e){return e;}throw new AssertionError("Expected refusal");}
 static Minecraft env(){return RouteStopEngineChecks.environment();}
 static Bee bee(Minecraft mc){return RouteStopEngineChecks.at(mc,new Bee(),20,20,20);}
 static Bee server(Bee client){Bee b=new Bee();b.id=client.id;b.uuid=client.uuid;return b;}
 static void publish(Minecraft mc,Bee server){publish(mc,server,mc.level.time,System.nanoTime(),true);}
 static void publish(Minecraft mc,Bee server,long tick,long nano,boolean complete){var row=NativeLivingObservation.read(server,tick,nano);NativeLivingObservation.publish(mc,Map.of(row.uuid(),row),complete);}
 static F admit(Minecraft mc){var r=request(0);var m=new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time,false,true,true);m.admissionRecheck(mc);m.admissionRawFence(mc);m.admissionEvidenceFence();var e=ClientActions.install(r,m);m.activate(e);return new F(mc,m,e,System.nanoTime());}
 record B(F f,Bee bee,Bee server){}
 static B start(){var mc=env();var b=bee(mc);var server=server(b);publish(mc,server);return new B(admit(mc),b,server);}
 static void clean(F f){ok(!f.entry().result.has("route_threat_stop")&&!f.m().admissionThreat()&&!f.m().spatialThreatProfile(),"no combat authority");}
 static void diagnostic(ClientActionRequest.Rejected e,String code){var j=e.routeEntityRejection;ok(j!=null&&j.get("profile").getAsString().equals(ScopedRouteStopPolicy.PROFILE_V2)&&j.get("policy").getAsString().equals(ScopedRouteStopPolicy.POLICY_V2),"bound v2 diagnostic");ok(e.getMessage().equals(code),"reason "+e.getMessage()+" expected "+code);}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);
  scenario("calm-exact-bee-complete-geometry-and-server-facts",()->{var b=start();b.f.m().beforeEffect(b.f.mc());var g=b.f.m().facts().getAsJsonObject("entity_guard");var row=g.getAsJsonArray("rows").get(0).getAsJsonObject();ok(g.get("schema_version").getAsInt()==2&&g.get("policy").getAsString().equals(ScopedRouteStopPolicy.POLICY_V2),"negotiated v2");ok(row.get("verdict").getAsString().equals("outside_context")&&row.has("aabb")&&row.has("velocity")&&row.has("lerp_target")&&row.has("projected_aabb"),"complete geometry");var n=row.getAsJsonObject("native_living");ok(n.get("current_target").isJsonNull()&&n.getAsJsonObject("bee").get("persistent_anger_target_uuid").isJsonNull()&&n.getAsJsonObject("bee_route").get("hive_pos").isJsonNull(),"explicit nulls");clean(b.f);});
  scenario("v1-legacy-threat-reject-identical-bee",()->{var b=start();var mc=b.f.mc();ClientActions.reset();var r=request(0);diagnosticV1(refused(()->new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time,false,true)));refused(()->new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time));refused(()->new ScopedLocalSegmentMovement(mc,SpatialThreatEngineChecks.request(),System.nanoTime(),mc.level.time,true));});
  scenario("native-exact-server-class-and-type",()->{Bee b=new Bee();ok(NativeBeeRouteObservation.read(b)!=null,"exact Bee sampled");class ModBee extends Bee{}ok(NativeBeeRouteObservation.read(new ModBee())==null,"subclass unknown");b.type=EntityType.SHEEP;ok(NativeBeeRouteObservation.read(b)==null,"registry mismatch unknown");var m=env();var c=bee(m);var server=server(c);server.type=EntityType.SHEEP;publish(m,server);diagnostic(refused(()->admit(m)),"route_bee_native_unconfirmed");});
  scenario("server-anger-sting-target-aggression-all-refuse",()->{for(int k=0;k<6;k++){var m=env();var c=bee(m);var s=server(c);switch(k){case 0->s.anger=1;case 1->s.stung=true;case 2->s.target=m.player;case 3->s.aggressive=true;case 4->s.angerTarget=m.player.uuid;case 5->s.alive=false;}publish(m,s);var e=refused(()->admit(m));ok(e.routeEntityRejection!=null,"bounded refusal "+k);ok(ClientActions.active==null,"no admission "+k);}});
  scenario("client-anger-stung-target-overrides-old-calm",()->{for(int k=0;k<3;k++){var m=env();var c=bee(m);publish(m,server(c));if(k==0)c.anger=1;if(k==1)c.stung=true;if(k==2)c.target=m.player;refused(()->admit(m));}});
  scenario("missing-stale-partial-identity-tick-and-future-refuse",()->{for(int k=0;k<8;k++){var m=env();var c=bee(m);var s=server(c);long tick=m.level.time,nano=System.nanoTime();if(k==0){}else{if(k==1)nano-=251_000_000L;if(k==2)tick-=6;if(k==3)s.id++;if(k==4)s.uuid=UUID.randomUUID();if(k==5)nano+=1_000_000_000L;publish(m,s,tick,nano,k!=6);if(k==7)NativeLivingObservation.reset();}diagnostic(refused(()->admit(m)),"route_bee_native_unconfirmed");}});
  scenario("current-body-lerp-velocity-combination-and-touch-refuse",()->{for(int k=0;k<5;k++){var m=env();var c=bee(m);if(k==0){c.x=c.tx=.5;c.z=c.tz=2;}if(k==1){c.z=c.tz=.5;c.tx=.5;}if(k==2){c.z=c.tz=.5;c.velocity=new Vec3(-.2,0,0);}if(k==3){c.x=c.tx=4.3;c.z=c.tz=.5;}if(k==4){c.z=c.tz=.5;c.tx=12;c.velocity=new Vec3(-.06,0,0);}publish(m,server(c));refused(()->admit(m));}});
  scenario("unknown-far-and-client-subclass-still-refuse",()->{var m=env();class ModBee extends Bee{}RouteStopEngineChecks.at(m,new ModBee(),20,1000,1000);refused(()->admit(m));var m2=env();var c=bee(m2);c.type=EntityType.SHEEP;refused(()->admit(m2));var m3=env();RouteStopEngineChecks.at(m3,new Entity(),20,1000,1000);refused(()->admit(m3));});
  scenario("new-fresh-batch-each-callback-nectar-hive-flower-accepted",()->{var b=start();for(int i=0;i<6;i++){b.server.nectar=i%2==0;b.server.hive=i%2==0?new BlockPos(1,2,3):null;b.server.flower=i%2==1?new BlockPos(4,5,6):null;publish(b.f.mc(),b.server);b.f.entry().ticks=i;b.f.m().beforeEffect(b.f.mc());}clean(b.f);});
  scenario("same-callback-equivalent-calm-republication-accepted",()->{for(String hook:List.of("friction","shape","state")){var b=start();Hooks.once(hook,0,()->publish(b.f.mc(),b.server));b.f.m().beforeEffect(b.f.mc());clean(b.f);}});
  scenario("same-callback-anger-publication-context-and-client-change",()->{for(int k=0;k<4;k++){var b=start();int mode=k;Hooks.once("friction",0,()->{switch(mode){case 0->{b.server.anger=20;publish(b.f.mc(),b.server);}case 1->NativeLivingObservation.reset();case 2->b.bee.stung=true;case 3->{b.f.mc().level.entities.remove(b.bee);RouteStopEngineChecks.at(b.f.mc(),new Bee(),20,20,20);}}});refused(()->b.f.m().beforeEffect(b.f.mc()));clean(b.f);}});
  scenario("legacy-living-json-omits-route-only-extension",()->{var b=start();JsonObject j=new JsonObject();NativeLivingObservation.append(b.f.mc(),b.bee,j,NativeLivingObservation.capture(b.f.mc()));var n=j.getAsJsonObject("native_living");ok(!n.has("bee_route")&&n.getAsJsonObject("bee").keySet().equals(Set.of("angry","remaining_anger_ticks","persistent_anger_target_uuid")),"legacy snapshot exact keys unchanged");});
  scenario("server-source-expires-during-world-hook",()->{var b=start();publish(b.f.mc(),b.server,b.f.mc().level.time,System.nanoTime()-235_000_000L,true);Hooks.once("friction",0,()->{try{Thread.sleep(25);}catch(InterruptedException e){throw new AssertionError(e);}});refused(()->b.f.m().beforeEffect(b.f.mc()));clean(b.f);});
  scenario("v2-without-bees-needs-no-server-batch",()->{var m=env();NativeLivingObservation.reset();var f=admit(m);Hooks.once("friction",0,NativeLivingObservation::reset);f.m().beforeEffect(m);clean(f);});
  scenario("source-expiry-at-final-no-hook-fence",()->{var b=start();var r=ScopedRouteStopEntities.capture(b.f.mc(),ScopedLocalSegmentPolicy.route(.5,1,.5,List.of(new ScopedLocalSegmentPolicy.Point(1.5,1,.5))),0,true);try{Thread.sleep(260);}catch(InterruptedException e){throw new AssertionError(e);}diagnostic(refused(r::finalFence),"route_bee_native_stale");});
  scenario("native-store-old-context-cannot-republish",()->{var b=start();var f=NativeLivingObservation.capture(b.f.mc());NativeLivingObservation.reset();ok(!NativeLivingObservation.STORE.publish(f.batch()),"old publication blocked");ok(!NativeLivingObservation.currentBatch(f),"old context invalid");});
  scenario("reentrant-terminal-or-new-owner-not-mutated",()->{for(int k=0;k<3;k++){var b=start();int mode=k;var replacement=new ClientActions.RuntimeAction(new ActionRegistry.Entry(request(0)),null);String[] before={null};String replacementBefore=replacement.entry.result.toString();Hooks.once("friction",0,()->{if(mode!=2)ClientActions.finish(mode==0?"cancelled":"succeeded",mode==0?"cancel_requested":"path_reached");else ClientActions.active=replacement;before[0]=b.f.entry().result.toString();publish(b.f.mc(),b.server);});refused(()->b.f.m().beforeEffect(b.f.mc()));ok(before[0].equals(b.f.entry().result.toString()),"original terminal immutable");ok(replacementBefore.equals(replacement.entry.result.toString()),"replacement unchanged");}});
  scenario("motion-boundary-unsafe-publication-retains-unknown-no-retry",()->{var b=start();b.f.m().markAttempted();ScopedLocalSegmentDispatch.arm(b.f.m());Hooks.once("friction",0,()->{b.server.anger=20;publish(b.f.mc(),b.server);});ok(!ScopedLocalSegmentDispatch.beforeMove(b.f.mc().player,MoverType.SELF,b.f.mc().player.velocity),"move rejected");ok(b.f.entry().result.get("unknown_outcome").getAsBoolean()&&b.f.entry().result.get("effect_outcome").getAsString().equals("unknown"),"unknown retained");clean(b.f);});
  scenario("v2-terrain-equivalence-retained",()->{var b=start();b.f.mc().level.contextWall=true;refused(()->b.f.m().beforeEffect(b.f.mc()));clean(b.f);});
  var success=start();for(int i=1;i<=4;i++){publish(success.f.mc(),success.server);sample(success.f,i,new double[]{0,.8,1.1,1.4,1.47}[i],1,true,-.0784,0);}success.f.m().markAttempted();writeFixture(out.resolve("route-bee-success"),success.f);
  var mutableMc=env();WorldGeneration.value="00000000-0000-4000-8000-000000000001";var mutableClient=bee(mutableMc);var mutableServer=server(mutableClient);
  var mutableHive=new BlockPos.MutableBlockPos(1,2,3);var mutableFlower=new BlockPos.MutableBlockPos(4,5,6);mutableServer.hive=mutableHive;mutableServer.flower=mutableFlower;publish(mutableMc,mutableServer);
  var mutableSuccess=admit(mutableMc);mutableHive.set(10,20,30);mutableFlower.set(40,50,60);
  for(int i=1;i<=4;i++)sample(mutableSuccess,i,new double[]{0,.8,1.1,1.4,1.47}[i],1,true,-.0784,0);
  mutableSuccess.m().markAttempted();writeFixture(out.resolve("route-bee-mutable-success"),mutableSuccess);
  var reject=start();reject.server.anger=20;publish(reject.f.mc(),reject.server);var e=refused(()->reject.f.m().beforeEffect(reject.f.mc()));reject.f.entry().status="cancelled";reject.f.entry().reason=e.getMessage();writeFixture(out.resolve("route-bee-rejection"),reject.f);
  var motion=start();motion.f.m().markAttempted();ScopedLocalSegmentDispatch.arm(motion.f.m());Hooks.once("friction",0,()->{motion.server.anger=20;publish(motion.f.mc(),motion.server);});ScopedLocalSegmentDispatch.beforeMove(motion.f.mc().player,MoverType.SELF,motion.f.mc().player.velocity);writeFixture(out.resolve("route-bee-motion"),motion.f);
  var terrain=start();terrain.f.mc().level.fluid=true;var terrainError=refused(()->terrain.f.m().beforeEffect(terrain.f.mc()));terrain.f.entry().status="cancelled";terrain.f.entry().reason=terrainError.getMessage();writeFixture(out.resolve("route-bee-terrain"),terrain.f);
  var m=env();var b=bee(m);b.stung=true;publish(m,server(b));var denied=refused(()->admit(m));Files.writeString(out.resolve("bee-admission-rejection.json"),BridgeJson.toJson(denied.response()),StandardOpenOption.CREATE_NEW);
  JsonObject report=new JsonObject();report.addProperty("assertions",assertions);report.add("cases",cases);report.addProperty("scope","Unchanged native route policy/readers/controller and production server row extraction against explicit synthetic game readers; no runtime/AI/physics claim");Files.writeString(out.resolve("route-bee-result.json"),report.toString(),StandardOpenOption.CREATE_NEW);System.out.println("PASS assertions="+assertions);
 }
 static void diagnosticV1(ClientActionRequest.Rejected e){ok(e.routeEntityRejection.get("profile").getAsString().equals(ScopedRouteStopPolicy.PROFILE),"v1 unchanged");}
}
